def transform(grid):
    """Compress each 3x3 patch to its non-5 color."""
    out = []
    for r in range(0, len(grid), 3):
        row = []
        for c in range(0, len(grid[0]), 3):
            colors = {grid[i][j] for i in range(r, min(r + 3, len(grid)))
                      for j in range(c, min(c + 3, len(grid[0]))) if grid[i][j] != 5}
            row.append(next(iter(colors), 5))
        out.append(row)
    return out
